head.script:
scwin.func = function(str, num, row) {
    return row % 2 == 0 ? "a" : "b";
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.__isSorted = function(col_id) {
    var arr = [];
    WebSquare.wUnit.getJq("#gridView1_body_tbody tr").not(".w2grid_hidedRow").find('td[col_id="' + col_id + '"]').each(function(i, el) {
        arr.push(WebSquare.wUnit.getJq(el).text());
    })
    for (var i = 0; i < arr.length; i++) {
        if (arr[i] > arr[i + 1]) {
            return false;
        }
    }
    return true;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. 브라우저에서 6번째 컬럼 expr 을 더블클릭하여 Sort 한다.
    //3. In the browser, double-click the 6th column expr to sort.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_column2')");
    WebSquare.wUnit.addCommand("pause", "100");
    // verify step 3. 6번째 컬럼 expression 이 Sort 된다.
    //3. The sixth column expression is sorted.
    WebSquare.wUnit.addCommand("assert", "scwin.__isSorted('column4')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step
    //
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_column9')");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step
    //
    WebSquare.wUnit.addCommand("assert", "scwin.__isSorted('num')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
